export type WebDateMode = 'date' | 'datetime';

export type WebDateFormat = 'dd/MM/yyyy' | 'MM/dd/yyyy' | 'yyyy-MM-dd';

/** Empty values clear a field. Nonempty values use local ISO calendar fields. */
export function isWebDateValue(value: unknown): value is string;

/** Shared model projection for Designer and generated browser applications. */
export function configureWebDate(component: WebDate, props: Readonly<Record<string, unknown>>, name: string): void;

/** Masked local date/date-time input. Values never imply a UTC time zone. */
export class WebDate extends WebComponent<HTMLElement> {
    #private;
    constructor(element: HTMLElement);
    get mode(): WebDateMode;
    set mode(value: WebDateMode);
    get dateFormat(): WebDateFormat;
    set dateFormat(value: WebDateFormat);
    get showSeconds(): boolean;
    set showSeconds(value: boolean);
    get mask(): string;
    /** Canonical YYYY-MM-DD or YYYY-MM-DDTHH:mm[:ss]; empty while incomplete/invalid. */
    get value(): string;
    set value(value: string);
    /** Display text, including an incomplete or invalid draft. */
    get text(): string;
    set text(value: string);
    /** A fresh Date at the start of the local day; null for an empty/incomplete/impossible date. */
    get date(): Date | null;
    set date(value: Date | null);
    /** A fresh local Date including time; date mode returns the start of the local day. */
    get datetime(): Date | null;
    set datetime(value: Date | null);
    get min(): string;
    set min(value: string);
    get max(): string;
    set max(value: string);
    get required(): boolean;
    set required(value: boolean);
    get readOnly(): boolean;
    set readOnly(value: boolean);
    get placeholder(): string;
    set placeholder(value: string);
    get accessibleLabel(): string;
    set accessibleLabel(value: string);
    get showCalendar(): boolean;
    set showCalendar(value: boolean);
    get visible(): boolean;
    set visible(value: boolean);
    get enabled(): boolean;
    set enabled(value: boolean);
    get tabIndex(): number;
    set tabIndex(value: number);
    focus(options?: FocusOptions): void;
    get valid(): boolean;
    get validationMessage(): string;
    checkValidity(): boolean;
    reportValidity(): boolean;
    clear(): void;
    setNow(): void;
    /** Opens the calendar aligned to the field, with a minimum popup width of 260px. */
    showPicker(): boolean;
    set onChange(handler: WebComponentEventHandler<this> | null);
    set onInput(handler: WebComponentEventHandler<this> | null);
    dispose(): void;
}
